import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';

// Generates a SIMULATED call transcript for the MDX Dial prototype.
// No real audio exists yet; Telnyx recording + transcription will replace this
// at production time. For now we ask the LLM to produce a plausible short
// transcript based on call metadata, and return a placeholder recording URL.
export default async function(req) {
  try {
    const base44 = createClientFromRequest(req);
    const user = await base44.auth.me();
    if (!user) return Response.json({ error: 'Unauthorized' }, { status: 401 });

    const body = await req.json().catch(() => ({}));
    const peerName = String(body.peerName || 'the caller').slice(0, 80);
    const direction = body.direction === 'inbound' ? 'inbound' : 'outbound';
    const duration = Math.max(0, Math.min(3600, Number(body.durationSeconds) || 0));

    const prompt =
      `You are simulating a phone call transcript for a VoIP dialer prototype (no real audio exists). ` +
      `Write a brief, realistic ${direction} phone call transcript between "You" and ${peerName}. ` +
      `Keep it to 4-6 short lines of dialogue, professional and natural, ending gracefully. ` +
      `Format each line as plain text prefixed with "You:" or "${peerName}:".`;

    const result = await base44.asServiceRole.integrations.Core.InvokeLLM({ prompt });
    const transcript = typeof result === 'string' ? result : result?.text || String(result || '');
    const recordingUrl = `https://telnyx.simulated/recordings/${crypto.randomUUID()}.mp3`;

    return Response.json({ transcript, recording_url: recordingUrl });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}

import { createClientFromRequest } from 'npm:@base44/sdk@0.8.52';

// Automation: when a call is missed, automatically text the caller an apology
// on behalf of the assigned user. Invoked by the "Missed Call Auto-Text"
// workflow. Creates a simulated outbound Message (real SMS via Telnyx at launch).
export default async function(req) {
  try {
    const base44 = createClientFromRequest(req);
    const body = await req.json().catch(() => ({}));
    const peerNumber = String(body.peerNumber || '').slice(0, 30);
    const peerName = String(body.peerName || 'Unknown').slice(0, 80);
    const assignedUserId = String(body.assignedUserId || '');
    if (!peerNumber || !assignedUserId) return Response.json({ skipped: true });

    await base44.asServiceRole.entities.Message.create({
      conversation_id: peerNumber,
      direction: 'outbound',
      body: "Sorry I missed your call — I'll get back to you shortly. (Auto-reply)",
      peer_number: peerNumber,
      peer_name: peerName,
      assigned_user_id: assignedUserId,
      status: 'sent',
      read: false,
      simulated: true,
    });
    return Response.json({ sent: true });
  } catch (error) {
    return Response.json({ error: error.message }, { status: 500 });
  }
}

{
  "name": "Missed Call Auto-Text",
  "description": "When a call is missed, automatically texts the caller an apology on behalf of the assigned user.",
  "trigger": {
    "config": {
      "trigger_type": "entity",
      "entity_name": "CallLog",
      "events": [
        "update"
      ]
    },
    "condition": "${ .trigger.data.status == \"missed\" and .trigger.old_data.status != \"missed\" }"
  },
  "definition": {
    "document": {
      "dsl": "1.0.0",
      "name": "missed_call_auto_text",
      "version": "1.0",
      "namespace": "base44"
    },
    "do": [
      {
        "send_text": {
          "call": "invoke_backend_function",
          "with": {
            "function_name": "sendMissedCallAutoText",
            "args": {
              "peerNumber": "${ .trigger.data.peer_number }",
              "peerName": "${ .trigger.data.peer_name }",
              "assignedUserId": "${ .trigger.data.assigned_user_id }"
            }
          },
          "then": "end",
          "x-base44": {
            "title": "Send auto-text",
            "description": "Apologize to the missed caller"
          }
        }
      }
    ]
  }
}

import { Toaster } from "@/components/ui/toaster"
import { QueryClientProvider } from '@tanstack/react-query'
import { queryClientInstance } from '@/lib/query-client'
import { BrowserRouter as Router, Route, Routes } from 'react-router-dom';
import PageNotFound from './lib/PageNotFound';
import { AuthProvider, useAuth } from '@/lib/AuthContext';
import UserNotRegisteredError from '@/components/UserNotRegisteredError';
import ScrollToTop from './components/ScrollToTop';
import Login from '@/pages/Login';
import Register from '@/pages/Register';
import ForgotPassword from '@/pages/ForgotPassword';
import ResetPassword from '@/pages/ResetPassword';
import AppShell from '@/components/AppShell';
import RoleRedirect from '@/components/RoleRedirect';
import EmployeeDialer from '@/pages/EmployeeDialer';
import ReceptionistConsole from '@/pages/ReceptionistConsole';
import AdminConsole from '@/pages/AdminConsole';
// Add page imports here

const AuthenticatedApp = () => {
  const { isLoadingAuth, isLoadingPublicSettings, authError, navigateToLogin } = useAuth();

  // Show loading spinner while checking app public settings or auth
  if (isLoadingPublicSettings || isLoadingAuth) {
    return (
      <div className="fixed inset-0 flex items-center justify-center">
        <div className="w-8 h-8 border-4 border-slate-200 border-t-slate-800 rounded-full animate-spin"></div>
      </div>
    );
  }

  // Handle authentication errors
  if (authError) {
    if (authError.type === 'user_not_registered') {
      return <UserNotRegisteredError />;
    } else if (authError.type === 'auth_required') {
      // Redirect to login automatically
      navigateToLogin();
      return null;
    }
  }

  // Render the main app
  return (
    <Routes>
      <Route element={<AppShell />}>
        <Route path="/" element={<RoleRedirect />} />
        <Route path="/dialer" element={<EmployeeDialer />} />
        <Route path="/receptionist" element={<ReceptionistConsole />} />
        <Route path="/admin" element={<AdminConsole />} />
      </Route>
      <Route path="*" element={<PageNotFound />} />
    </Routes>
  );
};


function App() {

  return (
    <AuthProvider>
      <QueryClientProvider client={queryClientInstance}>
        <Router>
          <ScrollToTop />
          <Routes>
            <Route path="/login" element={<Login />} />
            <Route path="/register" element={<Register />} />
            <Route path="/forgot-password" element={<ForgotPassword />} />
            <Route path="/reset-password" element={<ResetPassword />} />
            <Route path="/*" element={<AuthenticatedApp />} />
          </Routes>
        </Router>
        <Toaster />
      </QueryClientProvider>
    </AuthProvider>
  )
}

