import { useEffect, useState, useCallback } from "react";
import { Search, UserPlus, MessageSquare, Pencil, Smartphone } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone, initials, colorForName } from "@/lib/phoneUtils";
import { canPickContacts, pickContacts } from "@/lib/deviceContacts";
import ContactEditor from "@/components/dialer/ContactEditor";

const EMPTY = { name: "", company: "", phone: "", email: "", type: "company", department: "", notes: "" };

export default function ContactsList({ onCall, onMessage }) {
  const [items, setItems] = useState([]);
  const [query, setQuery] = useState("");
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);
  const [importing, setImporting] = useState(false);

  const refresh = useCallback(async () => {
    try {
      const q = query ? { name: { $regex: query, $options: "i" } } : {};
      const page = await base44.entities.Contact.filter(q, { sort: "name", limit: 50 });
      setItems(page.items);
    } catch (e) {
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [query]);

  useEffect(() => { refresh(); }, [refresh]);

  const save = async (e) => {
    e.preventDefault();
    const c = editing;
    if (c.id) await base44.entities.Contact.update(c.id, c);
    else await base44.entities.Contact.create(c);
    setEditing(null);
    refresh();
  };
  const remove = async (c) => { await base44.entities.Contact.delete(c.id); setEditing(null); refresh(); };

  const importFromPhone = async () => {
    setImporting(true);
    try {
      const picked = await pickContacts();
      if (picked.length) {
        await base44.entities.Contact.bulkCreate(
          picked.map((p) => ({ ...EMPTY, ...p, type: "personal" }))
        );
      }
      refresh();
    } finally {
      setImporting(false);
    }
  };

  if (loading && !items.length) return <div className="flex flex-1 items-center justify-center text-sm text-zinc-400">Loading…</div>;

  return (
    <div className="flex flex-1 flex-col px-4 pb-4">
      <div className="relative mb-3 mt-2">
        <Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-zinc-400" />
        <input
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Search contacts"
          className="w-full rounded-full bg-zinc-100 py-2 pl-9 pr-4 text-sm outline-none focus:ring-2 focus:ring-indigo-200"
        />
      </div>

      <div className="mb-3 flex gap-2">
        <button
          onClick={() => setEditing({ ...EMPTY })}
          className="flex flex-1 items-center justify-center gap-1.5 rounded-lg bg-indigo-600 px-3 py-2 text-sm font-medium text-white hover:bg-indigo-500"
        >
          <UserPlus className="h-4 w-4" /> Add contact
        </button>
        {canPickContacts() && (
          <button
            onClick={importFromPhone}
            disabled={importing}
            className="flex items-center justify-center gap-1.5 rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm font-medium text-zinc-700 hover:bg-zinc-50 disabled:opacity-50"
          >
            <Smartphone className="h-4 w-4" /> {importing ? "Importing…" : "Import from phone"}
          </button>
        )}
      </div>

      {!items.length ? (
        <div className="flex flex-1 flex-col items-center justify-center gap-2 text-zinc-400">
          <UserPlus className="h-8 w-8" />
          <p className="text-sm">{query ? "No matches" : "No contacts yet"}</p>
        </div>
      ) : (
        <div className="flex-1 overflow-y-auto pt-2">
          {items.map((c) => (
            <div key={c.id} className="flex items-center gap-2 rounded-xl px-2 py-2.5 hover:bg-zinc-50">
              <button onClick={() => onCall(c.phone, c.name)} className="flex min-w-0 flex-1 items-center gap-3 text-left">
                <div
                  className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full text-xs font-semibold text-white"
                  style={{ backgroundColor: c.avatar_color || colorForName(c.name) }}
                >
                  {initials(c.name)}
                </div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-zinc-900">{c.name}</p>
                  <p className="truncate text-xs text-zinc-500">{c.company || formatPhone(c.phone)}</p>
                </div>
              </button>
              {onMessage && (
                <button
                  onClick={() => onMessage(c.phone, c.name)}
                  className="rounded-full p-2 text-zinc-400 hover:bg-zinc-100 hover:text-indigo-600"
                >
                  <MessageSquare className="h-4 w-4" />
                </button>
              )}
              <button
                onClick={() => setEditing({ ...c })}
                className="rounded-full p-2 text-zinc-400 hover:bg-zinc-100 hover:text-zinc-700"
              >
                <Pencil className="h-4 w-4" />
              </button>
            </div>
          ))}
        </div>
      )}

      {editing && (
        <ContactEditor
          contact={editing}
          setContact={setEditing}
          onSave={save}
          onClose={() => setEditing(null)}
          onDelete={remove}
        />
      )}
    </div>
  );
}

import { useEffect, useState, useCallback } from "react";
import { Voicemail, Play, Trash2, Check } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone, timeAgo, formatDuration } from "@/lib/phoneUtils";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

export default function VoicemailList() {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openId, setOpenId] = useState(null);

  const refresh = useCallback(async () => {
    try {
      const page = await base44.entities.Voicemail.filter({}, { sort: "-received_at", limit: 50 });
      setItems(page.items);
    } catch (e) {
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const unsub = base44.entities.Voicemail.subscribe(() => refresh());
    return () => { if (typeof unsub === "function") unsub(); };
  }, [refresh]);

  const markListened = async (vm) => {
    if (!vm.listened) await base44.entities.Voicemail.update(vm.id, { listened: true });
  };
  const remove = async (vm) => { await base44.entities.Voicemail.delete(vm.id); };

  if (loading) return <div className="flex flex-1 items-center justify-center text-sm text-zinc-400">Loading…</div>;
  if (!items.length) return (
    <div className="flex flex-1 flex-col items-center justify-center gap-2 text-zinc-400">
      <Voicemail className="h-8 w-8" />
      <p className="text-sm">No voicemails</p>
    </div>
  );

  return (
    <div className="flex-1 overflow-y-auto px-4 pb-4 pt-2">
      {items.map((vm) => (
        <div key={vm.id} className="mb-2 rounded-xl bg-white p-3 ring-1 ring-zinc-200">
          <button
            onClick={() => { setOpenId(openId === vm.id ? null : vm.id); markListened(vm); }}
            className="flex w-full items-center gap-3 text-left"
          >
            <div className={`flex h-10 w-10 items-center justify-center rounded-full ${vm.listened ? "bg-zinc-100" : "bg-indigo-100"}`}>
              <Play className={`h-4 w-4 ${vm.listened ? "text-zinc-400" : "text-indigo-600"}`} />
            </div>
            <div className="min-w-0 flex-1">
              <p className="truncate text-sm font-medium text-zinc-900">{vm.from_name || "Unknown"}</p>
              <p className="text-xs text-zinc-500">{formatPhone(vm.from_number)} · {timeAgo(vm.received_at)}</p>
            </div>
            {!vm.listened && <span className="h-2 w-2 rounded-full bg-indigo-500" />}
          </button>
          {openId === vm.id && (
            <div className="mt-3 border-t border-zinc-100 pt-3">
              <div className="mb-2 flex items-center gap-2">
                <SimulatedBadge />
                <span className="text-xs text-zinc-400">{formatDuration(vm.duration_seconds)}</span>
              </div>
              <p className="text-sm text-zinc-600">{vm.transcript}</p>
              <div className="mt-2 flex gap-2">
                <button onClick={() => markListened(vm)} className="flex items-center gap-1 rounded-lg bg-zinc-100 px-2.5 py-1.5 text-xs text-zinc-600 hover:bg-zinc-200">
                  <Check className="h-3.5 w-3.5" /> Mark read
                </button>
                <button onClick={() => remove(vm)} className="flex items-center gap-1 rounded-lg bg-red-50 px-2.5 py-1.5 text-xs text-red-600 hover:bg-red-100">
                  <Trash2 className="h-3.5 w-3.5" /> Delete
                </button>
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

import { useEffect, useRef, useState } from "react";
import { Phone, PhoneOff, Voicemail } from "lucide-react";
import { formatPhone } from "@/lib/phoneUtils";
import { acceptCall, declineCall, endCall } from "@/lib/callActions";
import { playRingtone } from "@/lib/ringtones";
import { useMyExtension } from "@/hooks/useMyExtension";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

// Full-screen ringing overlay. Handles inbound (accept/decline/voicemail)
// and outbound (calling… with end) states. Plays the user's chosen ringtone
// for inbound calls while ringing.
export default function IncomingCallOverlay({ call }) {
  const { user } = useMyExtension();
  const stopRef = useRef(null);

  useEffect(() => {
    if (!call || call.direction !== "inbound") return;
    const soundOn = user?.sound_enabled !== false && user?.data?.sound_enabled !== false;
    const ringtone = user?.ringtone || user?.data?.ringtone || "Classic";
    if (soundOn) stopRef.current = playRingtone(ringtone);
    return () => stopRef.current?.();
  }, [call?.id, user]);

  if (!call) return null;
  const isInbound = call.direction === "inbound";

  const stopRing = () => stopRef.current?.();
  const handleAccept = async () => { stopRing(); await acceptCall(call); };
  const handleDecline = async () => { stopRing(); await declineCall(call, { leaveVoicemail: false }); };
  const handleVoicemail = async () => { stopRing(); await declineCall(call, { leaveVoicemail: true }); };
  const handleEnd = async () => { stopRing(); await endCall(call); };

  return (
    <div className="fixed inset-0 z-50 flex flex-col items-center justify-between bg-zinc-950/95 px-6 py-12 text-white backdrop-blur">
      <div className="flex flex-col items-center gap-3 pt-10">
        <SimulatedBadge />
        <p className="text-sm font-medium text-zinc-400">
          {isInbound ? "Incoming call" : "Calling…"} · ext {call.extension_number}
        </p>
      </div>

      <div className="flex flex-col items-center gap-2">
        <div className="flex h-28 w-28 items-center justify-center rounded-full bg-white/10 text-3xl font-semibold ring-1 ring-white/20">
          {(call.peer_name || "?").slice(0, 1).toUpperCase()}
        </div>
        <h2 className="mt-4 text-2xl font-semibold">{call.peer_name || "Unknown"}</h2>
        <p className="text-lg text-zinc-300">{formatPhone(call.peer_number)}</p>
      </div>

      <div className="flex w-full max-w-sm justify-center">
        {isInbound ? (
          <div className="flex items-center justify-between gap-4">
            <button onClick={handleDecline} className="flex h-16 w-16 flex-col items-center justify-center gap-1 rounded-full bg-red-500/90 text-white transition hover:bg-red-500">
              <PhoneOff className="h-6 w-6" /><span className="text-[10px] font-medium">Decline</span>
            </button>
            <button onClick={handleVoicemail} className="flex h-16 w-16 flex-col items-center justify-center gap-1 rounded-full bg-white/10 text-white transition hover:bg-white/20">
              <Voicemail className="h-6 w-6" /><span className="text-[10px] font-medium">Voicemail</span>
            </button>
            <button onClick={handleAccept} className="flex h-16 w-16 flex-col items-center justify-center gap-1 rounded-full bg-green-500 text-white transition hover:bg-green-400">
              <Phone className="h-6 w-6" /><span className="text-[10px] font-medium">Accept</span>
            </button>
          </div>
        ) : (
          <button onClick={handleEnd} className="flex h-16 w-16 flex-col items-center justify-center gap-1 rounded-full bg-red-500 text-white transition hover:bg-red-400">
            <PhoneOff className="h-6 w-6" /><span className="text-[10px] font-medium">End</span>
          </button>
        )}
      </div>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Volume2, Headphones, Bluetooth, Phone, ChevronRight, X } from "lucide-react";

const QUICK = [
  { id: "speaker", label: "Speaker", icon: Volume2 },
  { id: "headset", label: "Headset", icon: Headphones },
  { id: "bluetooth", label: "Bluetooth", icon: Bluetooth },
  { id: "voip", label: "VoIP Device", icon: Phone },
];

// In-call audio output picker: quick options plus a "More" list of real
// audio output devices detected on the device (requires mic permission to
// show labels). Selection is tracked locally; real routing is wired up at
// production time alongside the Telnyx audio bridge.
export default function AudioDevicePicker({ selected, onSelect, onClose }) {
  const [devices, setDevices] = useState([]);
  const [showMore, setShowMore] = useState(false);

  useEffect(() => {
    if (!navigator.mediaDevices?.enumerateDevices) return;
    navigator.mediaDevices
      .enumerateDevices()
      .then((d) => setDevices(d.filter((x) => x.kind === "audiooutput" && x.label)))
      .catch(() => {});
  }, []);

  return (
    <div className="mx-auto mb-6 w-full max-w-md rounded-2xl bg-white/5 p-3 ring-1 ring-white/10">
      <div className="mb-2 flex items-center justify-between px-1">
        <span className="text-sm font-medium">Audio output</span>
        <button onClick={onClose}><X className="h-4 w-4 text-zinc-400" /></button>
      </div>

      <div className="grid grid-cols-2 gap-2">
        {QUICK.map((o) => {
          const Icon = o.icon;
          const active = selected === o.id;
          return (
            <button
              key={o.id}
              onClick={() => onSelect(o.id)}
              className={`flex items-center gap-2 rounded-lg px-3 py-2.5 text-sm transition ${
                active ? "bg-white text-zinc-900" : "bg-white/10 text-white hover:bg-white/20"
              }`}
            >
              <Icon className="h-4 w-4" /> {o.label}
            </button>
          );
        })}
      </div>

      <button
        onClick={() => setShowMore((s) => !s)}
        className="mt-2 flex w-full items-center justify-between rounded-lg bg-white/5 px-3 py-2 text-sm text-zinc-200 hover:bg-white/10"
      >
        <span>More</span>
        <ChevronRight className={`h-4 w-4 transition ${showMore ? "rotate-90" : ""}`} />
      </button>

      {showMore && (
        <div className="mt-2 space-y-1">
          {devices.length === 0 && (
            <p className="px-2 py-1 text-xs text-zinc-400">
              No additional devices detected. Grant microphone access to list connected headsets and Bluetooth devices.
            </p>
          )}
          {devices.map((d) => (
            <button
              key={d.deviceId}
              onClick={() => onSelect(d.deviceId)}
              className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm hover:bg-white/10"
            >
              <span className="truncate">{d.label}</span>
              {selected === d.deviceId && <span className="text-xs text-indigo-300">Selected</span>}
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useCallback } from "react";
import { MessageSquare, Plus } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { fetchConversations } from "@/lib/messaging";
import { formatPhone, timeAgo, initials, colorForName } from "@/lib/phoneUtils";
import { useMyExtension } from "@/hooks/useMyExtension";

export default function ConversationList({ onOpen }) {
  const { user } = useMyExtension();
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [composing, setComposing] = useState(false);
  const [num, setNum] = useState("");

  const refresh = useCallback(async () => {
    if (!user) return;
    try {
      setItems(await fetchConversations(user.id));
    } catch {
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, [user]);

  useEffect(() => {
    refresh();
    const unsub = base44.entities.Message.subscribe(() => refresh());
    return () => { if (typeof unsub === "function") unsub(); };
  }, [refresh]);

  const startNew = () => {
    if (!num.trim()) return;
    onOpen(num.trim(), "");
    setNum("");
    setComposing(false);
  };

  return (
    <div className="flex flex-1 flex-col px-4 pb-4">
      <div className="mb-3 mt-2 flex items-center justify-between">
        <h2 className="text-base font-semibold text-zinc-900">Messages</h2>
