              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-medium text-zinc-900">
                  {m.peer_name || formatPhone(m.peer_number)}
                </p>
                <p className="truncate text-xs text-zinc-500">
                  {m.direction === "outbound" ? "You: " : ""}
                  {m.body}
                </p>
              </div>
              <span className="shrink-0 text-[11px] text-zinc-400">{timeAgo(m.created_date)}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

import { useEffect, useState, useCallback, useRef } from "react";
import { ArrowLeft, Send, Trash2, Check, CheckCheck } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { fetchConversation, sendMessage, markConversationRead } from "@/lib/messaging";
import { formatPhone, clockTime } from "@/lib/phoneUtils";
import { playTone } from "@/lib/ringtones";
import { useMyExtension } from "@/hooks/useMyExtension";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

const REACTIONS = ["👍", "❤️", "😂", "😮", "🙏"];

export default function ConversationView({ peerNumber, peerName, onBack }) {
  const { user } = useMyExtension();
  const [items, setItems] = useState([]);
  const [body, setBody] = useState("");
  const [loading, setLoading] = useState(true);
  const [typing, setTyping] = useState(false);
  const [pickerFor, setPickerFor] = useState(null);
  const endRef = useRef(null);
  const typingTimer = useRef(null);

  const refresh = useCallback(async () => {
    if (!user) return;
    try {
      const msgs = await fetchConversation(user.id, peerNumber);
      setItems(msgs);
      markConversationRead(user.id, peerNumber);
    } catch {
      /* ignore */
    } finally {
      setLoading(false);
    }
  }, [user, peerNumber]);

  useEffect(() => {
    refresh();
    const unsub = base44.entities.Message.subscribe(() => refresh());
    return () => { if (typeof unsub === "function") unsub(); };
  }, [refresh]);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [items.length, typing]);

  useEffect(() => () => clearTimeout(typingTimer.current), []);

  const send = async (e) => {
    e.preventDefault();
    if (!body.trim() || !user) return;
    const text = body.trim();
    setBody("");
    playTone("sent");
    setTyping(true);
    clearTimeout(typingTimer.current);
    typingTimer.current = setTimeout(() => setTyping(false), 2600);
    await sendMessage({ user, peerNumber, peerName, body: text });
  };

  const react = async (m, emoji) => {
    setPickerFor(null);
    await base44.entities.Message.update(m.id, { reaction: m.reaction === emoji ? "" : emoji });
  };
  const remove = async (m) => {
    setPickerFor(null);
    await base44.entities.Message.delete(m.id);
  };

  return (
    <div className="flex flex-1 flex-col">
      <header className="flex items-center gap-3 border-b border-zinc-200 px-3 py-2.5">
        <button onClick={onBack} className="rounded-full p-2 text-zinc-500 hover:bg-zinc-100">
          <ArrowLeft className="h-5 w-5" />
        </button>
        <div className="min-w-0 flex-1">
          <p className="truncate text-sm font-semibold text-zinc-900">{peerName || formatPhone(peerNumber)}</p>
          <p className="truncate text-xs text-zinc-500">{formatPhone(peerNumber)}</p>
        </div>
        <SimulatedBadge />
      </header>

      <div className="flex-1 space-y-1.5 overflow-y-auto px-4 py-3">
        {loading ? (
          <p className="py-8 text-center text-sm text-zinc-400">Loading…</p>
        ) : !items.length ? (
          <p className="py-8 text-center text-sm text-zinc-400">No messages yet — say hello.</p>
        ) : (
          items.map((m) => (
            <div key={m.id} className={`flex ${m.direction === "outbound" ? "justify-end" : "justify-start"}`}>
              <div className="relative max-w-[78%]">
                <button
                  onClick={() => setPickerFor(pickerFor === m.id ? null : m.id)}
                  className={`block rounded-2xl px-3.5 py-2 text-left text-sm ${m.direction === "outbound" ? "bg-indigo-600 text-white" : "bg-zinc-100 text-zinc-900"}`}
                >
                  {m.body}
                  <span className={`mt-1 block text-right text-[10px] ${m.direction === "outbound" ? "text-indigo-200" : "text-zinc-400"}`}>
                    {clockTime(m.created_date)}
                    {m.direction === "outbound" && (m.read
                      ? <CheckCheck className="ml-1 inline h-3 w-3" />
                      : <Check className="ml-1 inline h-3 w-3" />)}
                  </span>
                </button>
                {m.reaction && (
                  <span className="absolute -bottom-2 right-2 rounded-full bg-white px-1.5 text-xs shadow ring-1 ring-zinc-200">{m.reaction}</span>
                )}
                {pickerFor === m.id && (
                  <div className="absolute z-10 mt-1 flex items-center gap-0.5 rounded-full bg-white p-1 shadow-lg ring-1 ring-zinc-200">
                    {REACTIONS.map((r) => (
                      <button key={r} onClick={() => react(m, r)} className="rounded-full px-1.5 py-0.5 text-base hover:bg-zinc-100">{r}</button>
                    ))}
                    <button onClick={() => remove(m)} className="rounded-full px-1.5 py-1 text-zinc-400 hover:bg-red-50 hover:text-red-500">
                      <Trash2 className="h-4 w-4" />
                    </button>
                  </div>
                )}
              </div>
            </div>
          ))
        )}
        {typing && (
          <div className="flex justify-start">
            <div className="rounded-2xl bg-zinc-100 px-3.5 py-2.5 text-sm text-zinc-500">
              <span className="animate-pulse">typing…</span>
            </div>
          </div>
        )}
        <div ref={endRef} />
      </div>

      <form onSubmit={send} className="flex items-center gap-2 border-t border-zinc-200 p-3 pb-[env(safe-area-inset-bottom)]">
        <input value={body} onChange={(e) => setBody(e.target.value)} placeholder="Text message" className="input" />
        <button type="submit" disabled={!body.trim()} className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-indigo-600 text-white hover:bg-indigo-500 disabled:opacity-40">
          <Send className="h-4 w-4" />
        </button>
      </form>
    </div>
  );
}

import { useState, useEffect } from "react";
import ConversationList from "@/components/dialer/ConversationList";
import ConversationView from "@/components/dialer/ConversationView";

export default function MessagesTab({ initialConv, onConsumed }) {
  const [active, setActive] = useState(null);

  useEffect(() => {
    if (initialConv) {
      setActive(initialConv);
      onConsumed?.();
    }
  }, [initialConv]);

  if (active) {
    return (
      <ConversationView
        peerNumber={active.peerNumber}
        peerName={active.peerName}
        onBack={() => setActive(null)}
      />
    );
  }
  return <ConversationList onOpen={(n, name) => setActive({ peerNumber: n, peerName: name })} />;
}

import { useEffect, useState, useCallback } from "react";
import { PhoneIncoming, PhoneOutgoing, PhoneMissed, Voicemail, FileText, Circle } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone, timeAgo, formatDuration } from "@/lib/phoneUtils";

const ICONS = {
  inbound: { icon: PhoneIncoming, color: "text-green-600" },
  outbound: { icon: PhoneOutgoing, color: "text-zinc-500" },
  missed: { icon: PhoneMissed, color: "text-red-500" },
};

export default function RecentsList({ onCall }) {
  const [items, setItems] = useState([]);
  const [loading, setLoading] = useState(true);
  const [openId, setOpenId] = useState(null);

  const refresh = useCallback(async () => {
    try {
      const page = await base44.entities.CallLog.filter(
        { status: { $in: ["ended", "missed", "voicemail"] } },
        { sort: "-started_at", limit: 50 }
      );
      setItems(page.items);
    } catch (e) {
      setItems([]);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    refresh();
    const unsub = base44.entities.CallLog.subscribe(() => refresh());
    return () => { if (typeof unsub === "function") unsub(); };
  }, [refresh]);

  if (loading) return <div className="flex flex-1 items-center justify-center text-sm text-zinc-400">Loading…</div>;
  if (!items.length) return <EmptyState label="No recent calls" />;

  return (
    <div className="flex-1 overflow-y-auto px-4 pb-4 pt-2">
      {items.map((c) => {
        const meta = ICONS[c.direction] || ICONS.outbound;
        const Icon = c.status === "voicemail" ? Voicemail : meta.icon;
        const color = c.status === "voicemail" ? "text-indigo-500" : c.status === "missed" ? "text-red-500" : meta.color;
        const open = openId === c.id;
        return (
          <div key={c.id} className="border-b border-zinc-100">
            <div className="flex items-center gap-3 py-3">
              <button onClick={() => onCall(c.peer_number, c.peer_name)} className="flex min-w-0 flex-1 items-center gap-3 text-left">
                <Icon className={`h-5 w-5 shrink-0 ${color}`} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-zinc-900">{c.peer_name || "Unknown"}</p>
                  <p className="truncate text-xs text-zinc-500">{formatPhone(c.peer_number)}</p>
                </div>
              </button>
              <div className="shrink-0 text-right">
                <div className="flex items-center justify-end gap-1.5">
                  {c.recording_url && <Circle className="h-2 w-2 fill-red-500 text-red-500" />}
                  <p className="text-xs text-zinc-400">{timeAgo(c.started_at || c.ended_at)}</p>
                </div>
                {c.duration_seconds > 0 && (
                  <p className="text-[11px] text-zinc-400">{formatDuration(c.duration_seconds)}</p>
                )}
              </div>
              {c.transcript && (
                <button
                  onClick={() => setOpenId(open ? null : c.id)}
                  className="ml-1 rounded-full p-1.5 text-zinc-400 hover:bg-zinc-100 hover:text-indigo-600"
                >
                  <FileText className="h-4 w-4" />
                </button>
              )}
            </div>
            {open && c.transcript && (
              <div className="mb-3 ml-8 whitespace-pre-line rounded-lg bg-zinc-50 p-3 text-xs leading-relaxed text-zinc-700">
                <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-zinc-400">Transcript</p>
                {c.transcript}
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function EmptyState({ label }) {
  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-2 text-zinc-400">
      <PhoneMissed className="h-8 w-8" />
      <p className="text-sm">{label}</p>
    </div>
  );
}

import { useEffect, useState } from "react";
import { Mic, MicOff, Phone, PhoneOff, Pause, Play, Grid3x3, ArrowRightLeft, X, Volume2 } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone, formatDuration } from "@/lib/phoneUtils";
import { endCall, holdCall, resumeCall, transferCall } from "@/lib/callActions";
import SimulatedBadge from "@/components/ui/SimulatedBadge";
import AudioDevicePicker from "@/components/dialer/AudioDevicePicker";

// Full-screen in-call experience for the current user's connected/on-hold call.
export default function ActiveCallScreen({ call, onEnded }) {
  const [muted, setMuted] = useState(false);
  const [keypad, setKeypad] = useState("");
  const [showTransfer, setShowTransfer] = useState(false);
  const [showKeypad, setShowKeypad] = useState(false);
  const [showAudio, setShowAudio] = useState(false);
  const [audioOutput, setAudioOutput] = useState("speaker");
  const [extensions, setExtensions] = useState([]);
  const [elapsed, setElapsed] = useState(0);
  const onHold = call.status === "on_hold";

  useEffect(() => {
    const start = call.started_at ? new Date(call.started_at).getTime() : Date.now();
    const id = setInterval(() => setElapsed(Math.floor((Date.now() - start) / 1000)), 1000);
    return () => clearInterval(id);
  }, [call.id, call.started_at]);

  useEffect(() => {
    base44.entities.Extension.filter({}, { sort: "number", limit: 100 })
      .then((p) => setExtensions(p.items.filter((e) => e.assigned_user_id && e.assigned_user_id !== call.assigned_user_id)))
      .catch(() => {});
  }, [call.id]);

  const handleEnd = async () => { await endCall(call); onEnded?.(); };
  const handleHold = async () => { await holdCall(call); };
  const handleResume = async () => { await resumeCall(call); };
  const handleTransfer = async (ext) => { await transferCall(call, ext); onEnded?.(); };

  return (
    <div className="fixed inset-0 z-50 flex flex-col bg-zinc-950 text-white">
      <div className="flex items-center justify-between px-6 pt-6">
        <SimulatedBadge />
        <div className="flex items-center gap-2">
          {call.recording && (
            <span className="flex items-center gap-1 rounded-full bg-red-500/20 px-2 py-0.5 text-xs text-red-300">
              <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-red-400" /> Rec
            </span>
          )}
          <span className="text-sm text-zinc-400">{onHold ? "On hold" : "Connected"}</span>
        </div>
      </div>

      <div className="flex flex-1 flex-col items-center justify-center gap-3">
        <div className="flex h-24 w-24 items-center justify-center rounded-full bg-white/10 text-2xl font-semibold ring-1 ring-white/20">
          {(call.peer_name || "?").slice(0, 1).toUpperCase()}
        </div>
        <h2 className="text-2xl font-semibold">{call.peer_name || "Unknown"}</h2>
        <p className="text-zinc-300">{formatPhone(call.peer_number)}</p>
        <p className="mt-1 font-mono text-sm text-zinc-400">{formatDuration(elapsed)}</p>
        {keypad && <p className="font-mono text-lg tracking-widest text-zinc-200">{keypad}</p>}
      </div>

      {showKeypad && (
        <div className="mx-auto mb-6 w-full max-w-xs rounded-2xl bg-white/5 p-3 ring-1 ring-white/10">
          <div className="mb-2 flex items-center justify-between px-1">
            <span className="text-sm font-medium">Keypad</span>
            <button onClick={() => setShowKeypad(false)}><X className="h-4 w-4 text-zinc-400" /></button>
          </div>
          <div className="grid grid-cols-3 gap-2">
            {["1","2","3","4","5","6","7","8","9","*","0","#"].map((d) => (
              <button key={d} onClick={() => setKeypad((k) => k + d)} className="rounded-lg bg-white/10 py-2.5 text-lg text-white hover:bg-white/20">{d}</button>
            ))}
          </div>
        </div>
      )}

      {showAudio && (
        <AudioDevicePicker
          selected={audioOutput}
          onSelect={(id) => { setAudioOutput(id); setShowAudio(false); }}
          onClose={() => setShowAudio(false)}
        />
      )}

      {showTransfer ? (
        <div className="mx-auto mb-6 w-full max-w-md rounded-2xl bg-white/5 p-3 ring-1 ring-white/10">
          <div className="mb-2 flex items-center justify-between px-1">
            <span className="text-sm font-medium">Transfer to…</span>
            <button onClick={() => setShowTransfer(false)}><X className="h-4 w-4 text-zinc-400" /></button>
          </div>
          <div className="max-h-52 space-y-1 overflow-y-auto">
            {extensions.length === 0 && <p className="px-2 py-3 text-sm text-zinc-400">No other extensions available.</p>}
            {extensions.map((ext) => (
              <button
                key={ext.id}
                onClick={() => handleTransfer(ext)}
                className="flex w-full items-center justify-between rounded-lg px-3 py-2 text-left text-sm hover:bg-white/10"
              >
                <span>{ext.assigned_user_name || ext.label}</span>
                <span className="text-zinc-400">ext {ext.number}</span>
              </button>
            ))}
          </div>
        </div>
      ) : (
        <div className="mx-auto mb-10 grid w-full max-w-sm grid-cols-3 gap-4">
          <CallButton active={muted} onClick={() => setMuted((m) => !m)} icon={muted ? MicOff : Mic} label="Mute" />
          <CallButton active={onHold} onClick={onHold ? handleResume : handleHold} icon={onHold ? Play : Pause} label={onHold ? "Resume" : "Hold"} />
          <CallButton active={showKeypad} onClick={() => setShowKeypad((s) => !s)} icon={Grid3x3} label="Keypad" />
          <CallButton active={showAudio} onClick={() => setShowAudio((s) => !s)} icon={Volume2} label="Audio" />
          <CallButton onClick={() => setShowTransfer(true)} icon={ArrowRightLeft} label="Transfer" />
          <button
            onClick={handleEnd}
            className="flex h-16 flex-col items-center justify-center gap-1 rounded-full bg-red-500 transition hover:bg-red-400"
          >
            <PhoneOff className="h-6 w-6" />
            <span className="text-[10px] font-medium">End</span>
          </button>
        </div>
      )}
    </div>
  );
}

function CallButton({ icon: Icon, label, active, onClick }) {
  return (
    <button
      onClick={onClick}
      className={`flex h-16 flex-col items-center justify-center gap-1 rounded-full transition ${
        active ? "bg-white text-zinc-900" : "bg-white/10 text-white hover:bg-white/20"
      }`}
    >
      <Icon className="h-5 w-5" />
      <span className="text-[10px] font-medium">{label}</span>
    </button>
  );
}

import { useState, useEffect } from "react";
import { X, PhoneIncoming } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { simulateInboundCall } from "@/lib/callActions";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

const SAMPLE_CALLERS = [
  { name: "Jordan Avery", number: "+1 (415) 555-0142" },
  { name: "Morgan Bell", number: "+1 (628) 555-0188" },
  { name: "Riley Chen", number: "+1 (212) 555-0117" },
  { name: "Unknown Caller", number: "+1 (800) 555-0199" },
];

export default function SimulateCallDialog({ open, onClose, extensions }) {
  const [extNumber, setExtNumber] = useState("");
  const [callerIdx, setCallerIdx] = useState(0);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    if (open && extensions.length && !extNumber) setExtNumber(extensions[0].number);
  }, [open, extensions, extNumber]);

  if (!open) return null;
  const target = extensions.find((e) => e.number === extNumber);

  const handleSimulate = async () => {
    if (!target) return;
    setBusy(true);
    const caller = SAMPLE_CALLERS[callerIdx];
    try {
      await simulateInboundCall({ fromNumber: caller.number, fromName: caller.name, toExtension: target });
      onClose();
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <div className="w-full max-w-md rounded-2xl bg-white p-5 shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <PhoneIncoming className="h-5 w-5 text-indigo-600" />
            <h2 className="text-base font-semibold">Simulate inbound call</h2>
          </div>
          <button onClick={onClose}><X className="h-5 w-5 text-zinc-400" /></button>
        </div>

        <div className="mb-2"><SimulatedBadge /></div>

        <label className="mb-1 block text-xs font-medium text-zinc-500">Ring extension</label>
        <select
          value={extNumber}
          onChange={(e) => setExtNumber(e.target.value)}
          className="mb-3 w-full rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-200"
        >
          {extensions.map((e) => (
            <option key={e.id} value={e.number}>
              ext {e.number} · {e.assigned_user_name || e.label}
            </option>
          ))}
        </select>

        <label className="mb-1 block text-xs font-medium text-zinc-500">Caller</label>
        <select
          value={callerIdx}
          onChange={(e) => setCallerIdx(Number(e.target.value))}
          className="mb-4 w-full rounded-lg border border-zinc-200 bg-white px-3 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-200"
        >
          {SAMPLE_CALLERS.map((c, i) => (
            <option key={i} value={i}>{c.name} · {c.number}</option>
          ))}
        </select>

        <button
          onClick={handleSimulate}
          disabled={busy || !target}
          className="w-full rounded-lg bg-indigo-600 py-2.5 text-sm font-medium text-white transition hover:bg-indigo-500 disabled:opacity-50"
        >
          {busy ? "Sending…" : "Ring extension"}
        </button>
      </div>
    </div>
  );
}

