import { useState } from "react";
import { Phone, PhoneOff, Pause, ArrowRightLeft, UserCheck } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone } from "@/lib/phoneUtils";
import { endCall, parkCall, transferCall } from "@/lib/callActions";

const STATUS_STYLE = {
  ringing: "bg-amber-100 text-amber-700",
  connected: "bg-green-100 text-green-700",
  on_hold: "bg-zinc-100 text-zinc-600",
  parked: "bg-indigo-100 text-indigo-700",
};

export default function CallQueuePanel({ calls, extensions, receptionistUserId }) {
  const [transferFor, setTransferFor] = useState(null);

  const take = async (call) => {
    await base44.entities.CallLog.update(call.id, {
      assigned_user_id: receptionistUserId,
      assigned_user_name: "Receptionist",
      status: "connected",
      started_at: call.started_at || new Date().toISOString(),
    });
  };

  const doTransfer = async (call, ext) => {
    await transferCall(call, ext);
    setTransferFor(null);
  };

  if (!calls.length) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 text-zinc-400">
        <Phone className="h-8 w-8" />
        <p className="text-sm">No active calls in the queue</p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {calls.map((call) => {
        const isTransfer = transferFor === call.id;
        const others = extensions.filter((e) => e.assigned_user_id && e.assigned_user_id !== call.assigned_user_id);
        return (
          <div key={call.id} className="rounded-xl border border-zinc-200 bg-white p-4 shadow-sm">
            <div className="flex items-center justify-between">
              <div className="min-w-0">
                <p className="truncate text-sm font-semibold text-zinc-900">{call.peer_name || "Unknown"}</p>
                <p className="text-xs text-zinc-500">{formatPhone(call.peer_number)}</p>
              </div>
              <span className={`rounded-full px-2 py-0.5 text-[11px] font-medium capitalize ${STATUS_STYLE[call.status] || "bg-zinc-100"}`}>
                {call.status.replace("_", " ")}
              </span>
            </div>
            <p className="mt-1 text-xs text-zinc-400">
              ext {call.extension_number} · {call.assigned_user_name || "Unassigned"}
            </p>

            {isTransfer ? (
              <div className="mt-3 rounded-lg bg-zinc-50 p-2">
                <p className="mb-1 px-1 text-[11px] font-medium text-zinc-500">Transfer to…</p>
                <div className="max-h-32 space-y-1 overflow-y-auto">
                  {others.length === 0 && <p className="px-2 py-1 text-xs text-zinc-400">No other extensions.</p>}
                  {others.map((ext) => (
                    <button
                      key={ext.id}
                      onClick={() => doTransfer(call, ext)}
                      className="flex w-full items-center justify-between rounded-md px-2 py-1.5 text-left text-sm hover:bg-white"
                    >
                      <span>{ext.assigned_user_name || ext.label}</span>
                      <span className="text-zinc-400">ext {ext.number}</span>
                    </button>
                  ))}
                </div>
                <button onClick={() => setTransferFor(null)} className="mt-1 w-full text-center text-xs text-zinc-400 hover:text-zinc-600">
                  Cancel
                </button>
              </div>
            ) : (
              <div className="mt-3 flex flex-wrap gap-2">
                {call.status === "ringing" && (
                  <Action onClick={() => take(call)} icon={UserCheck} label="Take" tone="green" />
                )}
                <Action onClick={() => setTransferFor(call.id)} icon={ArrowRightLeft} label="Transfer" />
                {call.status === "connected" && (
                  <Action onClick={() => parkCall(call)} icon={Pause} label="Park" />
                )}
                <Action onClick={() => endCall(call)} icon={PhoneOff} label="End" tone="red" />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
}

function Action({ icon: Icon, label, onClick, tone }) {
  const tones = {
    green: "bg-green-50 text-green-700 hover:bg-green-100",
    red: "bg-red-50 text-red-700 hover:bg-red-100",
    default: "bg-zinc-100 text-zinc-700 hover:bg-zinc-200",
  };
  return (
    <button onClick={onClick} className={`flex items-center gap-1.5 rounded-lg px-3 py-1.5 text-xs font-medium ${tones[tone] || tones.default}`}>
      <Icon className="h-3.5 w-3.5" /> {label}
    </button>
  );
}

import { useEffect, useState } from "react";
import { Plus, Pencil, Trash2, X } from "lucide-react";
import { base44 } from "@/api/base44Client";

const EMPTY = { number: "", label: "", department: "", role: "employee", assigned_user_id: "", voicemail_enabled: true };

export default function ExtensionsManager() {
  const [items, setItems] = useState([]);
  const [users, setUsers] = useState([]);
  const [departments, setDepartments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [editing, setEditing] = useState(null);

  const refresh = async () => {
    const [exts, us, depts] = await Promise.all([
      base44.entities.Extension.filter({}, { sort: "number", limit: 100 }),
      base44.entities.User.list(),
      base44.entities.Department.filter({}, { sort: "name", limit: 50 }),
    ]);
    setItems(exts.items);
    setUsers(us.items || []);
    setDepartments(depts.items);
    setLoading(false);
  };

  useEffect(() => { refresh(); }, []);

  const save = async (e) => {
    e.preventDefault();
    const form = editing;
    const user = users.find((u) => u.id === form.assigned_user_id);
    const payload = {
      number: form.number,
      label: form.label,
      department: form.department,
      role: form.role,
      assigned_user_id: form.assigned_user_id,
      assigned_user_name: user?.full_name || user?.email || "",
      voicemail_enabled: form.voicemail_enabled,
      status: form.status || "available",
    };
    if (form.id) {
      await base44.entities.Extension.update(form.id, payload);
    } else {
      const created = await base44.entities.Extension.create(payload);
      form.id = created.id;
    }
    if (user) {
      await base44.entities.User.update(user.id, { extension_number: form.number, phone_role: form.role });
    }
    setEditing(null);
    refresh();
  };

  const remove = async (ext) => {
    await base44.entities.Extension.delete(ext.id);
    refresh();
  };

  if (loading) return <p className="py-8 text-center text-sm text-zinc-400">Loading…</p>;

  return (
    <div>
      <div className="mb-3 flex items-center justify-between">
        <p className="text-sm text-zinc-500">{items.length} extensions</p>
        <button onClick={() => setEditing({ ...EMPTY })} className="flex items-center gap-1.5 rounded-lg bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white hover:bg-indigo-500">
          <Plus className="h-4 w-4" /> Add extension
        </button>
      </div>

      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">
        {items.map((ext) => (
          <div key={ext.id} className="rounded-xl border border-zinc-200 bg-white p-4">
            <div className="flex items-start justify-between">
              <div>
                <p className="text-lg font-semibold text-zinc-900">ext {ext.number}</p>
                <p className="text-sm text-zinc-500">{ext.label || "—"}</p>
              </div>
              <div className="flex gap-1">
                <button onClick={() => setEditing({ ...ext })} className="rounded p-1 text-zinc-400 hover:bg-zinc-100 hover:text-zinc-700"><Pencil className="h-4 w-4" /></button>
                <button onClick={() => remove(ext)} className="rounded p-1 text-zinc-400 hover:bg-red-50 hover:text-red-600"><Trash2 className="h-4 w-4" /></button>
              </div>
            </div>
            <dl className="mt-3 space-y-1 text-sm">
              <Row label="Department" value={ext.department || "—"} />
              <Row label="Role" value={ext.role} cap />
              <Row label="Assigned" value={ext.assigned_user_name || "—"} />
              <Row label="Voicemail" value={ext.voicemail_enabled ? "On" : "Off"} />
            </dl>
          </div>
        ))}
      </div>

      {editing && (
        <ExtDialog
          form={editing}
          setForm={setEditing}
          users={users}
          departments={departments}
          onSave={save}
          onClose={() => setEditing(null)}
        />
      )}
    </div>
  );
}

function Row({ label, value, cap }) {
  return (
    <div className="flex items-center justify-between gap-3">
      <dt className="text-zinc-400">{label}</dt>
      <dd className={`text-right text-zinc-700 ${cap ? "capitalize" : ""}`}>{value}</dd>
    </div>
  );
}

function ExtDialog({ form, setForm, users, departments, onSave, onClose }) {
  return (
    <div className="fixed inset-0 z-40 flex items-center justify-center bg-black/40 p-4" onClick={onClose}>
      <form onSubmit={onSave} className="w-full max-w-md rounded-2xl bg-white p-5 shadow-xl" onClick={(e) => e.stopPropagation()}>
        <div className="mb-4 flex items-center justify-between">
          <h2 className="text-base font-semibold">{form.id ? "Edit extension" : "Add extension"}</h2>
          <button type="button" onClick={onClose}><X className="h-5 w-5 text-zinc-400" /></button>
        </div>
        <div className="grid grid-cols-2 gap-3">
          <Field label="Number"><input required value={form.number} onChange={(e) => setForm({ ...form, number: e.target.value })} className="input" /></Field>
          <Field label="Label"><input value={form.label} onChange={(e) => setForm({ ...form, label: e.target.value })} className="input" /></Field>
          <Field label="Department">
            <select value={form.department} onChange={(e) => setForm({ ...form, department: e.target.value })} className="input">
              <option value="">None</option>
              {departments.map((d) => <option key={d.id} value={d.name}>{d.name}</option>)}
            </select>
          </Field>
          <Field label="Role">
            <select value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })} className="input">
              <option value="employee">Employee</option>
              <option value="receptionist">Receptionist</option>
              <option value="admin">Admin</option>
            </select>
          </Field>
          <Field label="Assigned user" full>
            <select value={form.assigned_user_id} onChange={(e) => setForm({ ...form, assigned_user_id: e.target.value })} className="input">
              <option value="">Unassigned</option>
              {users.map((u) => <option key={u.id} value={u.id}>{u.full_name || u.email}</option>)}
            </select>
          </Field>
        </div>
        <label className="mt-3 flex items-center gap-2 text-sm text-zinc-600">
          <input type="checkbox" checked={form.voicemail_enabled} onChange={(e) => setForm({ ...form, voicemail_enabled: e.target.checked })} />
          Voicemail enabled
        </label>
        <button type="submit" className="mt-4 w-full rounded-lg bg-indigo-600 py-2.5 text-sm font-medium text-white hover:bg-indigo-500">Save</button>
      </form>
    </div>
  );
}

function Field({ label, full, children }) {
  return (
    <label className={full ? "col-span-2" : ""}>
      <span className="mb-1 block text-xs font-medium text-zinc-500">{label}</span>
      {children}
    </label>
  );
}

