import { useEffect, useState } from "react";
import { PhoneIncoming, PhoneOutgoing, PhoneMissed, Voicemail, FileText, Circle } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { formatPhone, timeAgo, formatDuration } from "@/lib/phoneUtils";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

const ICONS = {
  inbound: { icon: PhoneIncoming, color: "text-green-600" },
  outbound: { icon: PhoneOutgoing, color: "text-zinc-500" },
  missed: { icon: PhoneMissed, color: "text-red-500" },
};

export default function CallHistoryPanel() {
  const [items, setItems] = useState([]);
  const [stats, setStats] = useState({ total: 0, missed: 0, voicemail: 0 });
  const [loading, setLoading] = useState(true);
  const [openId, setOpenId] = useState(null);

  useEffect(() => {
    (async () => {
      try {
        const [page, total, missed, vm] = await Promise.all([
          base44.entities.CallLog.filter({ status: { $in: ["ended", "missed", "voicemail"] } }, { sort: "-started_at", limit: 50 }),
          base44.entities.CallLog.count({ status: { $in: ["ended", "missed", "voicemail"] } }),
          base44.entities.CallLog.count({ disposition: "missed" }),
          base44.entities.CallLog.count({ status: "voicemail" }),
        ]);
        setItems(page.items);
        setStats({ total, missed, voicemail: vm });
      } catch (e) {
        // ignore
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  return (
    <div>
      <div className="mb-4 grid grid-cols-3 gap-3">
        <Stat label="Total calls" value={stats.total} />
        <Stat label="Missed" value={stats.missed} tone="text-red-600" />
        <Stat label="Voicemails" value={stats.voicemail} tone="text-indigo-600" />
      </div>

      <div className="mb-3"><SimulatedBadge /></div>

      {loading ? (
        <p className="py-8 text-center text-sm text-zinc-400">Loading…</p>
      ) : !items.length ? (
        <p className="py-8 text-center text-sm text-zinc-400">No calls yet</p>
      ) : (
        <div className="space-y-2">
          {items.map((c) => {
            const meta = ICONS[c.direction] || ICONS.outbound;
            const Icon = c.status === "voicemail" ? Voicemail : meta.icon;
            const color = c.status === "voicemail" ? "text-indigo-500" : c.status === "missed" ? "text-red-500" : meta.color;
            const open = openId === c.id;
            return (
              <div key={c.id} className="rounded-xl border border-zinc-200 bg-white p-3">
                <div className="flex items-center gap-3">
                  <Icon className={`h-5 w-5 shrink-0 ${color}`} />
                  <div className="min-w-0 flex-1">
                    <p className="truncate text-sm font-medium text-zinc-900">{c.peer_name || "Unknown"}</p>
                    <p className="truncate text-xs text-zinc-500">
                      {formatPhone(c.peer_number)} · ext {c.extension_number || "—"}
                    </p>
                  </div>
                  <div className="shrink-0 text-right text-xs text-zinc-400">
                    <div className="flex items-center justify-end gap-1.5">
                      {c.recording_url && <Circle className="h-2 w-2 fill-red-500 text-red-500" />}
                      <p>{timeAgo(c.started_at || c.ended_at)}</p>
                    </div>
                    <p>{c.duration_seconds ? formatDuration(c.duration_seconds) : "—"}</p>
                  </div>
                  {c.transcript && (
                    <button
                      onClick={() => setOpenId(open ? null : c.id)}
                      className="ml-1 rounded-full p-1.5 text-zinc-400 hover:bg-zinc-100 hover:text-indigo-600"
                    >
                      <FileText className="h-4 w-4" />
                    </button>
                  )}
                </div>
                {open && c.transcript && (
                  <div className="mt-3 whitespace-pre-line rounded-lg bg-zinc-50 p-3 text-xs leading-relaxed text-zinc-700">
                    <p className="mb-1 text-[10px] font-semibold uppercase tracking-wide text-zinc-400">Transcript</p>
                    {c.transcript}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

function Stat({ label, value, tone }) {
  return (
    <div className="rounded-xl border border-zinc-200 bg-white p-4">
      <p className="text-xs font-medium uppercase text-zinc-500">{label}</p>
      <p className={`mt-1 text-2xl font-semibold ${tone || "text-zinc-900"}`}>{value}</p>
    </div>
  );
}

import { useEffect, useState } from "react";
import {
  ResponsiveContainer, BarChart, Bar, XAxis, YAxis, Tooltip, CartesianGrid,
  PieChart, Pie, Cell, Legend,
} from "recharts";
import { Phone, PhoneMissed, Voicemail, Users } from "lucide-react";
import { base44 } from "@/api/base44Client";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

const STATUS_COLORS = { available: "#22c55e", busy: "#f59e0b", offline: "#d4d4d8" };
const DIR_COLORS = ["#22c55e", "#6366f1", "#ef4444"];

export default function OverviewPanel() {
  const [stats, setStats] = useState({ total: 0, missed: 0, voicemail: 0, active: 0 });
  const [perDay, setPerDay] = useState([]);
  const [byDirection, setByDirection] = useState([]);
  const [extensions, setExtensions] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    (async () => {
      try {
        const [total, missed, vm, active, dayAgg, dirAgg, extPage] = await Promise.all([
          base44.entities.CallLog.count({ status: { $in: ["ended", "missed", "voicemail"] } }),
          base44.entities.CallLog.count({ disposition: "missed" }),
          base44.entities.CallLog.count({ status: "voicemail" }),
          base44.entities.CallLog.count({ status: { $in: ["ringing", "connected", "on_hold", "parked"] } }),
          base44.entities.CallLog.aggregate({ dateBucket: { field: "created_date", unit: "day" }, limit: 7, sort: "-_id" }),
          base44.entities.CallLog.aggregate({ groupBy: "direction" }),
          base44.entities.Extension.filter({}, { sort: "number", limit: 100 }),
        ]);
        setStats({ total, missed, voicemail: vm, active });
        const days = (dayAgg.rows || []).slice().reverse().map((r) => ({
          date: (r._id || r.date || "").slice(5),
          calls: r.count,
        }));
        setPerDay(days);
        setByDirection((dirAgg.rows || []).map((r) => ({ name: r.direction || "unknown", value: r.count })));
        setExtensions(extPage.items || []);
      } catch (e) {
        /* ignore */
      } finally {
        setLoading(false);
      }
    })();
  }, []);

  if (loading) return <p className="py-8 text-center text-sm text-zinc-400">Loading overview…</p>;

  return (
    <div className="space-y-6">
      <div className="mb-3"><SimulatedBadge /></div>

      <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
        <Stat icon={Phone} label="Total calls" value={stats.total} />
        <Stat icon={PhoneMissed} label="Missed" value={stats.missed} tone="text-red-600" />
        <Stat icon={Voicemail} label="Voicemails" value={stats.voicemail} tone="text-indigo-600" />
        <Stat icon={Users} label="Active now" value={stats.active} tone="text-green-600" />
      </div>

      <div className="grid gap-4 lg:grid-cols-3">
        <Card title="Calls — last 7 days" className="lg:col-span-2">
          <ResponsiveContainer width="100%" height={240}>
            <BarChart data={perDay}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f1f1" />
              <XAxis dataKey="date" tick={{ fontSize: 12 }} stroke="#9ca3af" />
              <YAxis allowDecimals={false} tick={{ fontSize: 12 }} stroke="#9ca3af" />
              <Tooltip />
              <Bar dataKey="calls" fill="#6366f1" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </Card>

        <Card title="By direction">
          <ResponsiveContainer width="100%" height={240}>
            <PieChart>
              <Pie data={byDirection} dataKey="value" nameKey="name" cx="50%" cy="50%" outerRadius={70} label>
                {byDirection.map((_, i) => (
                  <Cell key={i} fill={DIR_COLORS[i % DIR_COLORS.length]} />
                ))}
              </Pie>
              <Legend />
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </Card>
      </div>

      <Card title="Live extension status">
        {extensions.length === 0 ? (
          <p className="py-4 text-center text-sm text-zinc-400">No extensions configured</p>
        ) : (
          <div className="grid gap-2 sm:grid-cols-2 lg:grid-cols-3">
            {extensions.map((e) => (
              <div key={e.id} className="flex items-center gap-3 rounded-lg border border-zinc-200 p-3">
                <span className="h-2.5 w-2.5 rounded-full" style={{ backgroundColor: STATUS_COLORS[e.status] || "#d4d4d8" }} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-medium text-zinc-900">{e.assigned_user_name || e.label || "Unassigned"}</p>
                  <p className="text-xs text-zinc-500">ext {e.number} · {e.status}</p>
                </div>
              </div>
            ))}
          </div>
        )}
      </Card>
    </div>
  );
}

function Stat({ icon: Icon, label, value, tone }) {
  return (
    <div className="rounded-xl border border-zinc-200 bg-white p-4">
      <div className="flex items-center gap-2">
        <Icon className="h-4 w-4 text-zinc-400" />
        <p className="text-xs font-medium uppercase text-zinc-500">{label}</p>
      </div>
      <p className={`mt-1 text-2xl font-semibold ${tone || "text-zinc-900"}`}>{value}</p>
    </div>
  );
}

function Card({ title, className = "", children }) {
  return (
    <div className={`rounded-xl border border-zinc-200 bg-white p-4 ${className}`}>
      <p className="mb-3 text-sm font-semibold text-zinc-900">{title}</p>
      {children}
    </div>
  );
}

import * as React from "react"

const MOBILE_BREAKPOINT = 768

export function useIsMobile() {
  const [isMobile, setIsMobile] = React.useState(undefined)

  React.useEffect(() => {
    const mql = window.matchMedia(`(max-width: ${MOBILE_BREAKPOINT - 1}px)`)
    const onChange = () => {
      setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    }
    mql.addEventListener("change", onChange)
    setIsMobile(window.innerWidth < MOBILE_BREAKPOINT)
    return () => mql.removeEventListener("change", onChange);
  }, [])

  return !!isMobile
}

import * as React from "react"

export function useSize(ref) {
  const [size, setSize] = React.useState(null)

  // useLayoutEffect (not useEffect): the initial measurement must land before
  // the browser paints, so consumers can render their real content on the
  // very first painted frame instead of a guess. A ResizeObserver's first
  // callback arrives too late for that — by then an <img> src guess has
  // already been dispatched to the network.
  React.useLayoutEffect(() => {
    const element = ref.current
    if (!element) return

    const rect = element.getBoundingClientRect()
    setSize({ width: rect.width, height: rect.height })

    const observer = new ResizeObserver(([entry]) => {
      const { width, height } = entry.contentRect
      setSize({ width, height })
    })

    observer.observe(element)
    return () => observer.disconnect()
  }, [ref])

  return size
}

import { useEffect, useState, useCallback } from "react";
import { base44 } from "@/api/base44Client";
import { fetchActiveCalls } from "@/lib/callActions";

// Subscribes to live CallLog changes and keeps the active-call list fresh.
// all=false returns only the current user's active calls (employee view);
// all=true returns every active call (receptionist/admin view).
export function useActiveCalls({ all = false, userId } = {}) {
  const [calls, setCalls] = useState([]);
  const [loading, setLoading] = useState(true);
  const [tick, setTick] = useState(0);

  const refresh = useCallback(async () => {
    try {
      const items = await fetchActiveCalls({ all, userId });
      setCalls(items);
    } catch (e) {
      setCalls([]);
    } finally {
      setLoading(false);
    }
  }, [all, userId]);

  useEffect(() => {
    refresh();
    const unsubscribe = base44.entities.CallLog.subscribe(() => setTick((t) => t + 1));
    return () => {
      if (typeof unsubscribe === "function") unsubscribe();
    };
  }, [refresh]);

  useEffect(() => {
    if (tick === 0) return;
    refresh();
  }, [tick, refresh]);

  return { calls, loading, refresh };
}

import { useEffect, useState } from "react";
import { base44 } from "@/api/base44Client";

// Resolves the current user's profile + assigned extension.
export function useMyExtension() {
  const [user, setUser] = useState(null);
  const [extension, setExtension] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const me = await base44.auth.me();
        if (cancelled) return;
        setUser(me);
        const extNumber = me.extension_number || me.data?.extension_number;
        if (extNumber) {
          const page = await base44.entities.Extension.filter({ number: extNumber }, { limit: 1 });
          if (!cancelled && page.items?.length) setExtension(page.items[0]);
        } else {
          // Fall back to an extension assigned to this user.
          const page = await base44.entities.Extension.filter({ assigned_user_id: me.id }, { limit: 1 });
          if (!cancelled && page.items?.length) setExtension(page.items[0]);
        }
      } catch (e) {
        // not logged in or error — leave null
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return { user, extension, loading, setExtension };
}

import React, { createContext, useState, useContext, useEffect } from 'react';
import { base44 } from '@/api/base44Client';
import { appParams } from '@/lib/app-params';

const AuthContext = createContext();

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [isLoadingAuth, setIsLoadingAuth] = useState(true);
  const [isLoadingPublicSettings, setIsLoadingPublicSettings] = useState(true);
  const [authError, setAuthError] = useState(null);
  const [authChecked, setAuthChecked] = useState(false);
  const [appPublicSettings, setAppPublicSettings] = useState(null); // Contains only { id, public_settings }

  useEffect(() => {
    checkAppState();
  }, []);

  const checkAppState = async () => {
    try {
      setIsLoadingPublicSettings(true);
      setAuthError(null);

      try {
        const publicSettings = await base44.app.getPublicSettings();
        setAppPublicSettings(publicSettings);

        // If we got the app public settings successfully, check if user is authenticated
        if (appParams.token) {
          await checkUserAuth();
        } else {
          setIsLoadingAuth(false);
          setIsAuthenticated(false);
          setAuthChecked(true);
        }
        setIsLoadingPublicSettings(false);
      } catch (appError) {
        console.error('App state check failed:', appError);

        // Handle app-level errors
        if (appError.status === 403 && appError.data?.extra_data?.reason) {
          const reason = appError.data.extra_data.reason;
          if (reason === 'auth_required') {
            setAuthError({
              type: 'auth_required',
              message: 'Authentication required'
            });
          } else if (reason === 'user_not_registered') {
            setAuthError({
              type: 'user_not_registered',
              message: 'User not registered for this app'
            });
          } else {
            setAuthError({
              type: reason,
              message: appError.message
            });
          }
        } else {
          setAuthError({
            type: 'unknown',
            message: appError.message || 'Failed to load app'
          });
        }
        setIsLoadingPublicSettings(false);
        setIsLoadingAuth(false);
      }
    } catch (error) {
      console.error('Unexpected error:', error);
      setAuthError({
        type: 'unknown',
        message: error.message || 'An unexpected error occurred'
      });
      setIsLoadingPublicSettings(false);
      setIsLoadingAuth(false);
    }
  };

  const checkUserAuth = async () => {
    try {
      // Now check if the user is authenticated
      setIsLoadingAuth(true);
      const currentUser = await base44.auth.me();
      setUser(currentUser);
      setIsAuthenticated(true);
      setIsLoadingAuth(false);
      setAuthChecked(true);
    } catch (error) {
      console.error('User auth check failed:', error);
      setIsLoadingAuth(false);
      setIsAuthenticated(false);
      setAuthChecked(true);

      // If user auth fails, it might be an expired token
      if (error.status === 401 || error.status === 403) {
        setAuthError({
          type: 'auth_required',
          message: 'Authentication required'
        });
      }
    }
  };

  const logout = (shouldRedirect = true) => {
    setUser(null);
    setIsAuthenticated(false);

    if (shouldRedirect) {
      // Use the SDK's logout method which handles token cleanup and redirect
      base44.auth.logout(window.location.href);
    } else {
      // Just remove the token without redirect
      base44.auth.logout();
    }
  };

  const navigateToLogin = () => {
    // Use the SDK's redirectToLogin method
    base44.auth.redirectToLogin(window.location.href);
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isAuthenticated, 
      isLoadingAuth,
      isLoadingPublicSettings,
      authError,
      appPublicSettings,
      authChecked,
      logout,
      navigateToLogin,
      checkUserAuth,
      checkAppState
    }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

