export const isIframe = window.self !== window.top;

// Shared helpers for the MDX Dial prototype: formatting, avatars, durations.

export const AVATAR_COLORS = [
  "#6366f1", "#8b5cf6", "#ec4899", "#f43f5e", "#f97316",
  "#eab308", "#22c55e", "#14b8a6", "#0ea5e9", "#64748b"
];

export function colorForName(name) {
  if (!name) return AVATAR_COLORS[0];
  let hash = 0;
  for (let i = 0; i < name.length; i++) hash = name.charCodeAt(i) + ((hash << 5) - hash);
  return AVATAR_COLORS[Math.abs(hash) % AVATAR_COLORS.length];
}

export function initials(name) {
  if (!name) return "?";
  const parts = name.trim().split(/\s+/);
  if (parts.length === 1) return parts[0].slice(0, 2).toUpperCase();
  return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
}

export function formatPhone(input) {
  if (!input) return "";
  const digits = String(input).replace(/[^\d+]/g, "");
  // US-style 10 digit formatting for numbers without country code
  const d = digits.replace(/^\+1/, "").replace(/^\+/, "");
  if (d.length === 10) return `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}`;
  if (d.length === 7) return `${d.slice(0, 3)}-${d.slice(3)}`;
  return input;
}

export function formatDuration(seconds) {
  const s = Math.max(0, Math.floor(seconds || 0));
  const m = Math.floor(s / 60);
  const sec = s % 60;
  return `${m}:${String(sec).padStart(2, "0")}`;
}

export function timeAgo(iso) {
  if (!iso) return "";
  const diff = Date.now() - new Date(iso).getTime();
  const mins = Math.floor(diff / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hrs = Math.floor(mins / 60);
  if (hrs < 24) return `${hrs}h ago`;
  const days = Math.floor(hrs / 24);
  return `${days}d ago`;
}

export function clockTime(iso) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  } catch {
    return "";
  }
}

export function nowIso() {
  return new Date().toISOString();
}

export function secondsBetween(a, b) {
  if (!a || !b) return 0;
  return Math.max(0, Math.round((new Date(b).getTime() - new Date(a).getTime()) / 1000));
}

// Build and download a vCard (.vcf) so a contact can be saved into the phone's
// native contacts app. The web platform has no API to write directly to the
// device contacts, so a vCard import is the supported "push" path.

function esc(s) {
  return String(s || "").replace(/([\\;,])/g, "\\$1").replace(/\n/g, "\\n");
}

export function buildVCard(c) {
  return [
    "BEGIN:VCARD",
    "VERSION:3.0",
    `FN:${esc(c.name)}`,
    `TEL;TYPE=CELL:${esc(c.phone)}`,
    c.email ? `EMAIL:${esc(c.email)}` : null,
    c.company ? `ORG:${esc(c.company)}` : null,
    c.notes ? `NOTE:${esc(c.notes)}` : null,
    "END:VCARD",
  ].filter(Boolean).join("\n");
}

export function downloadVCard(c) {
  const blob = new Blob([buildVCard(c)], { type: "text/vcard" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = `${(c.name || "contact").replace(/\s+/g, "_")}.vcf`;
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
}

// Device contacts access via the Contacts Provider API (Chrome Android).
// Only "pull" (pick) is supported by the platform; there is no web API to
// write back to the device contacts, so push uses a vCard download instead.

export function canPickContacts() {
  return (
    typeof navigator !== "undefined" &&
    "contacts" in navigator &&
    typeof navigator.contacts.select === "function"
  );
}

export async function pickContacts() {
  if (!canPickContacts()) return [];
  try {
    const results = await navigator.contacts.select(["name", "tel", "email"], { multiple: true });
    const picked = (results || []).map((r) => ({
      name: Array.isArray(r.name) ? r.name[0] : r.name || "",
      phone: Array.isArray(r.tel) ? r.tel[0] : r.tel || "",
      email: Array.isArray(r.email) ? r.email[0] : r.email || "",
    }));
    return picked.filter((c) => c.phone);
  } catch {
    return [];
  }
}

// Simulated SMS messaging for the MDX Dial prototype.
// Messages are stored in the Message entity and clearly labeled simulated.
// Production will bridge real SMS through Telnyx; nothing here sends a real text.

import { base44 } from "@/api/base44Client";

export async function sendMessage({ user, peerNumber, peerName, body }) {
  const msg = await base44.entities.Message.create({
    conversation_id: peerNumber,
    direction: "outbound",
    body,
    peer_number: peerNumber,
    peer_name: peerName || "Unknown",
    assigned_user_id: user.id,
    status: "sent",
    read: false,
    simulated: true,
  });
  // Simulate an inbound reply so the conversation feels two-way in the prototype.
  setTimeout(() => {
    base44.entities.Message.create({
      conversation_id: peerNumber,
      direction: "inbound",
      body: "Thanks for your message — this is a simulated reply.",
      peer_number: peerNumber,
      peer_name: peerName || "Unknown",
      assigned_user_id: user.id,
      status: "delivered",
      read: false,
      simulated: true,
    }).catch(() => {});
    // Mark the user's outbound messages as read (simulated read receipt).
    base44.entities.Message.updateMany(
      { assigned_user_id: user.id, conversation_id: peerNumber, direction: "outbound" },
      { $set: { read: true } }
    ).catch(() => {});
  }, 2200);
  return msg;
}

// Latest message per conversation, most recent first.
export async function fetchConversations(userId) {
  const page = await base44.entities.Message.filter(
    { assigned_user_id: userId },
    { sort: "-created_date", limit: 50 }
  );
  const map = new Map();
  for (const m of page.items) {
    const cur = map.get(m.conversation_id);
    if (!cur || new Date(m.created_date) > new Date(cur.created_date)) {
      map.set(m.conversation_id, m);
    }
  }
  return Array.from(map.values()).sort(
    (a, b) => new Date(b.created_date) - new Date(a.created_date)
  );
}

export async function fetchConversation(userId, peerNumber) {
  const page = await base44.entities.Message.filter(
    { assigned_user_id: userId, conversation_id: peerNumber },
    { sort: "created_date", limit: 100 }
  );
  return page.items;
}

// Mark inbound messages in a conversation as read (clears the unread badge).
export async function markConversationRead(userId, peerNumber) {
  return base44.entities.Message.updateMany(
    { assigned_user_id: userId, conversation_id: peerNumber, direction: "inbound", read: { $ne: true } },
    { $set: { read: true } }
  ).catch(() => {});
}

export async function countUnreadMessages(userId) {
  return base44.entities.Message.count({ assigned_user_id: userId, direction: "inbound", read: { $ne: true } });
}

// Simulated call lifecycle for the MDX Dial prototype.
// Every call is created with simulated: true and is clearly labeled in the UI.
// Production will bridge real audio through Telnyx + Firebase; nothing here is live.

import { base44 } from "@/api/base44Client";
import { nowIso, secondsBetween } from "@/lib/phoneUtils";
import { generateCallTranscript } from "@/functions/generateCallTranscript";

const ACTIVE_STATUSES = ["ringing", "connected", "on_hold", "parked"];

export async function fetchActiveCalls({ all = false, userId } = {}) {
  const query = { status: { $in: ACTIVE_STATUSES } };
  if (!all && userId) query.assigned_user_id = userId;
  const page = await base44.entities.CallLog.filter(query, {
    sort: "-started_at",
    limit: 50,
  });
  return page.items;
}

// Start an outbound simulated call from the employee's extension.
export async function startOutboundCall({ user, extension, peerNumber, peerName }) {
  const call = await base44.entities.CallLog.create({
    direction: "outbound",
    status: "ringing",
    peer_number: peerNumber,
    peer_name: peerName || "Unknown",
    assigned_user_id: user.id,
    assigned_user_name: user.full_name || user.email,
    extension_number: extension?.number || user.extension_number,
    started_at: nowIso(),
    disposition: "completed",
    simulated: true,
  });
  // Simulate the remote party picking up after a short ring.
  setTimeout(() => {
    base44.entities.CallLog.update(call.id, { status: "connected", started_at: nowIso(), recording: true, recording_started_at: nowIso() });
  }, 1800);
  return call;
}

// Receptionist simulates an inbound call arriving at an extension.
export async function simulateInboundCall({ fromNumber, fromName, toExtension }) {
  return base44.entities.CallLog.create({
    direction: "inbound",
    status: "ringing",
    peer_number: fromNumber,
    peer_name: fromName || "Unknown Caller",
    assigned_user_id: toExtension.assigned_user_id,
    assigned_user_name: toExtension.assigned_user_name,
    extension_number: toExtension.number,
    started_at: nowIso(),
    disposition: "completed",
    simulated: true,
  });
}

export async function acceptCall(call) {
  return base44.entities.CallLog.update(call.id, {
    status: "connected",
    started_at: call.started_at || nowIso(),
    recording: true,
    recording_started_at: nowIso(),
  });
}

export async function endCall(call) {
  const ended_at = nowIso();
  const duration = secondsBetween(call.started_at || call.created_date, ended_at);
  const updated = await base44.entities.CallLog.update(call.id, {
    status: "ended",
    ended_at,
    duration_seconds: duration,
  });
  // Auto-transcribe recorded calls (simulated). Fired without blocking so the
  // call screen closes immediately; Telnyx will provide real audio at launch.
  if (call.recording) {
    generateCallTranscript({
      peerName: call.peer_name,
      direction: call.direction,
      durationSeconds: duration,
    })
      .then((res) => {
        const data = res?.data || res || {};
        if (data.transcript) {
          base44.entities.CallLog.update(call.id, {
            transcript: data.transcript,
            recording_url: data.recording_url,
          }).catch(() => {});
        }
      })
      .catch(() => {});
  }
  return updated;
}

export async function holdCall(call) {
  return base44.entities.CallLog.update(call.id, { status: "on_hold" });
}

export async function resumeCall(call) {
  return base44.entities.CallLog.update(call.id, { status: "connected" });
}

export async function parkCall(call) {
  return base44.entities.CallLog.update(call.id, { status: "parked" });
}

// Transfer: reassign the call to another extension and ring that user.
export async function transferCall(call, toExtension) {
  return base44.entities.CallLog.update(call.id, {
    assigned_user_id: toExtension.assigned_user_id,
    assigned_user_name: toExtension.assigned_user_name,
    extension_number: toExtension.number,
    status: "ringing",
    transferred_to: toExtension.number,
    disposition: "transferred",
  });
}

// Decline / miss an inbound call, optionally leaving a voicemail.
export async function declineCall(call, { leaveVoicemail = false } = {}) {
  if (leaveVoicemail) {
    await base44.entities.Voicemail.create({
      from_number: call.peer_number,
      from_name: call.peer_name,
      assigned_user_id: call.assigned_user_id,
      assigned_user_name: call.assigned_user_name,
      extension_number: call.extension_number,
      duration_seconds: 12,
      received_at: nowIso(),
      transcript: "Simulated voicemail transcript: the caller left a brief message.",
      listened: false,
      simulated: true,
    });
    return base44.entities.CallLog.update(call.id, {
      status: "voicemail",
      ended_at: nowIso(),
      disposition: "voicemail",
    });
  }
  return base44.entities.CallLog.update(call.id, {
    status: "missed",
    ended_at: nowIso(),
    disposition: "missed",
  });
}

// Web Audio-based ringtones and UI tones for the MDX Dial prototype.
// No audio asset files needed — tones are synthesized with oscillators.
// Production native builds will use the device ringtone picker instead.

let ctx;
function audio() {
  if (typeof window === "undefined") return null;
  if (!ctx) {
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return null;
    ctx = new AC();
  }
  if (ctx.state === "suspended") ctx.resume().catch(() => {});
  return ctx;
}

const RINGTONES = {
  Classic: [{ f: 440, d: 0.4 }, { f: 550, d: 0.4 }],
  Pulse: [{ f: 660, d: 0.2 }, { f: 0, d: 0.1 }, { f: 660, d: 0.2 }, { f: 0, d: 0.3 }],
  Marimba: [{ f: 523, d: 0.18 }, { f: 659, d: 0.18 }, { f: 784, d: 0.18 }, { f: 659, d: 0.18 }],
  Chime: [{ f: 523, d: 0.25 }, { f: 659, d: 0.25 }, { f: 784, d: 0.4 }],
};

export const RINGTONE_NAMES = ["Classic", "Pulse", "Marimba", "Chime", "Silent"];

function playNote(c, freq, start, dur, gain = 0.15) {
  if (!freq) return;
  const o = c.createOscillator();
  const g = c.createGain();
  o.type = "sine";
  o.frequency.value = freq;
  o.connect(g);
  g.connect(c.destination);
  const t = c.currentTime + start;
  g.gain.setValueAtTime(0, t);
  g.gain.linearRampToValueAtTime(gain, t + 0.02);
  g.gain.exponentialRampToValueAtTime(0.001, t + dur);
  o.start(t);
  o.stop(t + dur + 0.05);
}

// Plays a looping ringtone. Returns a stop() function.
export function playRingtone(name) {
  if (!name || name === "Silent") return () => {};
  const c = audio();
  if (!c) return () => {};
  const seq = RINGTONES[name] || RINGTONES.Classic;
  let stopped = false;
  let timer;
  const loop = () => {
    if (stopped) return;
    let t = 0;
    for (const n of seq) {
      playNote(c, n.f, t, n.d);
      t += n.d;
    }
    timer = setTimeout(loop, (t + 0.5) * 1000);
  };
  loop();
  return () => {
    stopped = true;
    clearTimeout(timer);
  };
}

// Short one-shot UI tones.
export function playTone(name) {
  const c = audio();
  if (!c) return;
  const map = {
    dial: { f: 800, d: 0.08 },
    sent: { f: 1200, d: 0.12 },
    message: { f: 660, d: 0.18 },
    end: { f: 300, d: 0.2 },
  };
  const n = map[name] || map.dial;
  playNote(c, n.f, 0, n.d, 0.08);
}

