import React, { useState } from "react";
import { Link, useSearchParams } from "react-router-dom";
import { base44 } from "@/api/base44Client";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Lock, Loader2, AlertTriangle } from "lucide-react";
import AuthLayout from "@/components/AuthLayout";

export default function ResetPassword() {
  const [searchParams] = useSearchParams();
  const resetToken = searchParams.get("token");

  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");
    if (newPassword !== confirmPassword) {
      setError("Passwords do not match");
      return;
    }
    setLoading(true);
    try {
      await base44.auth.resetPassword({ resetToken, newPassword });
      window.location.href = "/login";
    } catch (err) {
      setError(err.message || "Failed to reset password");
    } finally {
      setLoading(false);
    }
  };

  if (!resetToken) {
    return (
      <AuthLayout
        icon={AlertTriangle}
        title="Invalid reset link"
        subtitle="This password reset link is missing or invalid"
        footer={
          <Link to="/forgot-password" className="text-primary font-medium hover:underline">
            Request a new link
          </Link>
        }
      >
        <p className="text-sm text-foreground text-center">
          The link you used appears to be incomplete. Please request a new password reset email.
        </p>
      </AuthLayout>
    );
  }

  return (
    <AuthLayout
      icon={Lock}
      title="New password"
      subtitle="Enter your new password below"
    >
      {error && (
        <div className="mb-4 p-3 rounded-lg bg-destructive/10 text-destructive text-sm">
          {error}
        </div>
      )}
      <form onSubmit={handleSubmit} className="space-y-4">
        <div className="space-y-2">
          <Label htmlFor="password">New Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="password"
              type="password"
              autoComplete="new-password"
              autoFocus
              placeholder="••••••••"
              value={newPassword}
              onChange={(e) => setNewPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <div className="space-y-2">
          <Label htmlFor="confirm">Confirm Password</Label>
          <div className="relative">
            <Lock className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-muted-foreground" aria-hidden="true" />
            <Input
              id="confirm"
              type="password"
              autoComplete="new-password"
              placeholder="••••••••"
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="pl-10 h-12"
              required
            />
          </div>
        </div>
        <Button type="submit" className="w-full h-12 font-medium" disabled={loading}>
          {loading ? (
            <>
              <Loader2 className="w-4 h-4 mr-2 animate-spin" />
              Resetting...
            </>
          ) : (
            "Reset password"
          )}
        </Button>
      </form>
    </AuthLayout>
  );
}

import { useState } from "react";
import { Grid3x3, Clock, Users, Voicemail as VoicemailIcon, MessageSquare } from "lucide-react";
import { useMyExtension } from "@/hooks/useMyExtension";
import { startOutboundCall } from "@/lib/callActions";
import DialPad from "@/components/dialer/DialPad";
import RecentsList from "@/components/dialer/RecentsList";
import ContactsList from "@/components/dialer/ContactsList";
import VoicemailList from "@/components/dialer/VoicemailList";
import MessagesTab from "@/components/dialer/MessagesTab";

const TABS = [
  { id: "keypad", label: "Keypad", icon: Grid3x3 },
  { id: "recents", label: "Recents", icon: Clock },
  { id: "contacts", label: "Contacts", icon: Users },
  { id: "voicemail", label: "Voicemail", icon: VoicemailIcon },
  { id: "messages", label: "Messages", icon: MessageSquare },
];

export default function EmployeeDialer() {
  const { user, extension } = useMyExtension();
  const [tab, setTab] = useState("keypad");
  const [openConv, setOpenConv] = useState(null);

  const handleCall = async (number, name) => {
    if (!user) return;
    await startOutboundCall({ user, extension, peerNumber: number, peerName: name });
  };

  const openConversation = (peerNumber, peerName) => {
    setOpenConv({ peerNumber, peerName });
    setTab("messages");
  };

  return (
    <div className="flex h-full flex-col bg-white">
      <div className="flex flex-1 flex-col overflow-hidden">
        {tab === "keypad" && <DialPad onCall={handleCall} />}
        {tab === "recents" && <RecentsList onCall={handleCall} />}
        {tab === "contacts" && <ContactsList onCall={handleCall} onMessage={openConversation} />}
        {tab === "voicemail" && <VoicemailList />}
        {tab === "messages" && (
          <MessagesTab initialConv={openConv} onConsumed={() => setOpenConv(null)} />
        )}
      </div>

      <nav className="flex shrink-0 border-t border-zinc-200 bg-white/95 pb-[env(safe-area-inset-bottom)] backdrop-blur">
        {TABS.map((t) => {
          const Icon = t.icon;
          const active = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`flex flex-1 flex-col items-center gap-0.5 py-2.5 text-[11px] transition ${
                active ? "text-indigo-600" : "text-zinc-400"
              }`}
            >
              <Icon className="h-5 w-5" />
              {t.label}
            </button>
          );
        })}
      </nav>
    </div>
  );
}

import { useState, useEffect } from "react";
import { PhoneIncoming } from "lucide-react";
import { base44 } from "@/api/base44Client";
import { useActiveCalls } from "@/hooks/useActiveCalls";
import { useMyExtension } from "@/hooks/useMyExtension";
import CallQueuePanel from "@/components/receptionist/CallQueuePanel";
import DirectoryPanel from "@/components/receptionist/DirectoryPanel";
import SimulateCallDialog from "@/components/receptionist/SimulateCallDialog";
import SimulatedBadge from "@/components/ui/SimulatedBadge";

export default function ReceptionistConsole() {
  const { user } = useMyExtension();
  const { calls, loading } = useActiveCalls({ all: true });
  const [extensions, setExtensions] = useState([]);
  const [simOpen, setSimOpen] = useState(false);

  useEffect(() => {
    base44.entities.Extension.filter({}, { sort: "number", limit: 100 })
      .then((p) => setExtensions(p.items))
      .catch(() => {});
  }, []);

  const ringingCount = calls.filter((c) => c.status === "ringing").length;

  return (
    <div className="flex h-full flex-col bg-zinc-50">
      <header className="flex flex-col gap-3 border-b border-zinc-200 bg-white px-4 py-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-lg font-semibold text-zinc-900">Receptionist Console</h1>
          <p className="text-sm text-zinc-500">
            {calls.length} active · {ringingCount} ringing
          </p>
        </div>
        <div className="flex items-center gap-3">
          <SimulatedBadge />
          <button
            onClick={() => setSimOpen(true)}
            className="flex items-center gap-2 rounded-lg bg-indigo-600 px-3.5 py-2 text-sm font-medium text-white transition hover:bg-indigo-500"
          >
            <PhoneIncoming className="h-4 w-4" /> Simulate inbound
          </button>
        </div>
      </header>

      <div className="flex-1 overflow-y-auto p-4 lg:overflow-hidden">
        <div className="grid grid-cols-1 gap-4 lg:h-full lg:grid-cols-3">
          <section className="lg:col-span-2 lg:overflow-y-auto">
            {loading ? (
              <p className="py-8 text-center text-sm text-zinc-400">Loading queue…</p>
            ) : (
              <CallQueuePanel calls={calls} extensions={extensions} receptionistUserId={user?.id} />
            )}
          </section>
          <aside className="rounded-xl border border-zinc-200 bg-white p-3 lg:overflow-y-auto">
            <DirectoryPanel />
          </aside>
        </div>
      </div>

      <SimulateCallDialog open={simOpen} onClose={() => setSimOpen(false)} extensions={extensions} />
    </div>
  );
}

